import {createAdminClient,authenticateUser} from '../_shared/amazon/supabase.ts';
import {loadAmazonSpApiCredentials} from '../_shared/amazon/config.ts';
import {spApiRequest} from '../_shared/amazon/sp-api.ts';
import {shopifyAccountCredentials,shopifyStoredApplicationCredentials} from '../_shared/shopifyAuth.ts';
import {amazonCancellationXml,amazonFeedResult,shopifyCancellationInput} from '../_shared/orderCancellation.ts';
import {cancelCarrier,cancellationAccount,CancellationRejected} from '../_shared/cancelCarriers.ts';
const cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization, x-client-info, apikey, content-type','Access-Control-Allow-Methods':'POST, OPTIONS'};
const response=(data:unknown,status=200)=>new Response(JSON.stringify(data),{status,headers:{...cors,'Content-Type':'application/json'}});
async function sourceCancel(admin:any,order:any,op:any,refresh:boolean,beforeMutation:()=>Promise<void>){
 if(order.source_channel==='shopify'){
  const {account}=await cancellationAccount(admin,order,'shopify',true);const c=await shopifyAccountCredentials(admin,account,await shopifyStoredApplicationCredentials(admin,order.owner_id));
  const gql=async(query:string,variables:any)=>{const res=await fetch(`https://${c.shopDomain}/admin/api/${c.apiVersion}/graphql.json`,{method:'POST',headers:{'Content-Type':'application/json','X-Shopify-Access-Token':c.accessToken},body:JSON.stringify({query,variables}),signal:AbortSignal.timeout(25000)});const payload=await res.json();if(!res.ok||payload.errors?.length){const message=payload.errors?.map((e:any)=>e.message).join(' · ')||`Shopify (${res.status})`;if(/access denied|scope/i.test(message))throw new CancellationRejected('Falta el permiso write_orders en Shopify. Actualiza los permisos de la app y vuelve a conectar la tienda.');if((res.status>=400&&res.status<500&&res.status!==408&&res.status!==429)||(payload.errors?.length&&payload.errors.every((e:any)=>['ACCESS_DENIED','GRAPHQL_VALIDATION_FAILED','UNDEFINED_FIELD','VARIABLES_IN_ALLOWED_POSITION','variableRequiresValidType','undefinedField'].includes(e.extensions?.code))))throw new CancellationRejected(message);throw new Error(message);}return payload.data;};
  const id=String(order.order_id).startsWith('gid://')?order.order_id:`gid://shopify/Order/${order.order_id}`;
  const state=await gql('query($id:ID!){order(id:$id){id cancelledAt}}',{id});if(!state.order)throw new CancellationRejected('Shopify no encuentra este pedido.');if(state.order.cancelledAt)return {status:'confirmed',message:'Shopify confirma que el pedido está cancelado.'};
  if(refresh){if(op.remote_id){const job=await gql('query($id:ID!){job(id:$id){id done}}',{id:op.remote_id});if(job.job?.done)return {status:'unknown',message:'Shopify terminó la tarea, pero el pedido todavía no figura cancelado.'};}return {status:'pending',message:'Cancelación pendiente de confirmación en Shopify.'};}
  const input=shopifyCancellationInput(id,op.details);
  await beforeMutation();
  const data=await gql('mutation($orderId:ID!,$reason:OrderCancelReason!,$refundMethod:OrderCancelRefundMethodInput!,$restock:Boolean!,$notifyCustomer:Boolean!){orderCancel(orderId:$orderId,reason:$reason,refundMethod:$refundMethod,restock:$restock,notifyCustomer:$notifyCustomer){job{id done} orderCancelUserErrors{field message code} userErrors{field message}}}',input);
  const result=data.orderCancel,errors=[...(result.orderCancelUserErrors||[]),...(result.userErrors||[])];if(errors.length)throw new CancellationRejected(errors.map((e:any)=>e.message).join(' · '));
  return {status:'pending',remoteId:result.job?.id,message:'Shopify ha recibido la cancelación. Pendiente de confirmación.'};
 }
 if(order.source_channel!=='amazon')throw new CancellationRejected('Solo se pueden cancelar pedidos de origen Amazon o Shopify.');
 const {account}=await cancellationAccount(admin,order,'amazon',true);
 let query=admin.from('amazon_orders').select('amazon_account_id,marketplace_id,fulfillment_channel').eq('owner_id',order.owner_id).eq('amazon_order_id',order.order_id);
 if(account.linked_resource_id)query=query.eq('amazon_account_id',account.linked_resource_id);
 const local=await query.limit(2);if(local.error)throw local.error;if(local.data?.length!==1)throw new CancellationRejected('No se puede determinar de forma segura la cuenta del pedido Amazon.');const context=local.data[0];
 const credentials=await loadAmazonSpApiCredentials(admin,{amazonAccountId:context.amazon_account_id,integrationAccountId:account.id,ownerId:order.owner_id});
 const remote:any=await spApiRequest(`/orders/v0/orders/${encodeURIComponent(order.order_id)}`,{},credentials);const current=remote.payload||remote;
 if(current.FulfillmentChannel!=='MFN')throw new CancellationRejected('La cancelación desde ZENVIA solo admite pedidos FBM.');
 if(current.OrderStatus==='Canceled')return {status:'confirmed',message:'Amazon confirma que el pedido está cancelado.'};
 if(refresh){
  if(!op.remote_id)return {status:'unknown',message:'No hay identificador de solicitud. Comprueba el pedido en Amazon; no se reenviará la cancelación.'};
  const feed:any=await spApiRequest(`/feeds/2021-06-30/feeds/${encodeURIComponent(op.remote_id)}`,{},credentials);
  if(['FATAL','CANCELLED'].includes(feed.processingStatus))return {status:'rejected',message:'Amazon no procesó el fichero de cancelación.'};
  if(feed.processingStatus!=='DONE')return {status:'pending',message:'Amazon está procesando la cancelación.'};
  const doc:any=await spApiRequest(`/feeds/2021-06-30/documents/${encodeURIComponent(feed.resultFeedDocumentId)}`,{},credentials);const res=await fetch(doc.url,{signal:AbortSignal.timeout(20000)});if(!res.ok)throw new Error('No se pudo leer el informe de Amazon.');let body=res.body;if(doc.compressionAlgorithm==='GZIP'&&body)body=body.pipeThrough(new DecompressionStream('gzip'));const result=amazonFeedResult(await new Response(body).text());return result.status==='confirmed'?{status:'pending',message:'Amazon aceptó el fichero; pendiente de que el pedido figure cancelado.'}:result;
 }
 if(current.OrderStatus!=='Unshipped')throw new CancellationRejected(`Amazon no permite esta cancelación desde ZENVIA: estado ${current.OrderStatus}. Gestiona el pedido en Seller Central.`);
 // Use live lines so the cancellation covers the complete order.
 const itemIds:string[]=[];let token='';do{const result:any=await spApiRequest(`/orders/v0/orders/${encodeURIComponent(order.order_id)}/orderItems`,{query:token?{NextToken:token}:{}},credentials);const p=result.payload||result;for(const item of p.OrderItems||[])itemIds.push(String(item.OrderItemId));token=p.NextToken||'';}while(token);
 const xml=amazonCancellationXml(credentials.sellerId,order.order_id,itemIds,op.details.reason);
 const doc:any=await spApiRequest('/feeds/2021-06-30/documents',{method:'POST',maxAttempts:1,body:{contentType:'text/xml; charset=UTF-8'}},credentials);
 const uploaded=await fetch(doc.url,{method:'PUT',headers:{'Content-Type':'text/xml; charset=UTF-8'},body:xml,signal:AbortSignal.timeout(25000)});if(!uploaded.ok)throw new CancellationRejected('No se pudo subir el fichero de cancelación a Amazon.');
 await beforeMutation();
 const feed:any=await spApiRequest('/feeds/2021-06-30/feeds',{method:'POST',maxAttempts:1,body:{feedType:'POST_ORDER_ACKNOWLEDGEMENT_DATA',marketplaceIds:[context.marketplace_id],inputFeedDocumentId:doc.feedDocumentId}},credentials);
 return {status:'pending',remoteId:feed.feedId,message:'Amazon ha recibido la cancelación. Pendiente del informe de procesamiento.'};
}
Deno.serve(async(req:Request)=>{
 if(req.method==='OPTIONS')return new Response('ok',{headers:cors});if(req.method!=='POST')return response({error:'Método no permitido.'},405);
 try{
  const admin=createAdminClient(),caller=await authenticateUser(req,admin);if(caller.role!=='admin'&&!caller.permissions?.includes('orders'))return response({error:'No tienes permiso para gestionar pedidos.'},403);
  const body=await req.json(),owner=caller.data_owner_id;const found=await admin.from('fulfillment_orders').select('*').eq('id',body.orderId).eq('owner_id',owner).maybeSingle();if(found.error)throw found.error;const order=found.data;if(!order)return response({error:'Pedido no encontrado.'},404);
  const refresh=body.action==='refresh';if(!refresh&&body.action!=='cancel')return response({error:'Acción no válida.'},400);
  let operations:any[]=[];
  if(refresh){const result=await admin.from('order_cancellation_operations').select('*').eq('order_id',order.id).eq('owner_id',owner).in('status',['submitting','pending','unknown']);if(result.error)throw result.error;operations=result.data||[];}
  else{
   const kind=body.kind;if(!['label','order'].includes(kind))throw new Error('Acción de cancelación no válida.');
   const provider=kind==='label'?(order.shipping_provider||'sendcloud'):order.source_channel;
   const shipmentRef=String(order.shipping_remote_id||order.sendcloud_parcel_id||order.tracking_number||'');
   if(kind==='label'&&!shipmentRef)throw new Error('El pedido no tiene una etiqueta activa.');
   if(kind==='order'&&!['amazon','shopify'].includes(provider))throw new Error('Este origen no admite cancelación.');
   // Validate options before creating a durable operation.
   if(kind==='order'&&!['customer','inventory','address','other'].includes(body.reason))throw new Error('Selecciona el motivo de cancelación.');
   const claim=await admin.rpc('integration_start_cancellation',{p_order_id:order.id,p_owner_id:owner,p_kind:kind,p_provider:provider,p_reference:kind==='label'?`${provider}:${order.shipping_integration_account_id}:${shipmentRef}`:`${provider}:${order.source_integration_account_id}:${order.order_id}`,p_user_id:caller.user_id,p_details:{reason:body.reason||'other',refund:body.refund===true,restock:body.restock!==false,shipmentRef,trackingNumber:order.tracking_number,parcelId:order.sendcloud_parcel_id,shippingRemoteId:order.shipping_remote_id,shippingAccountId:order.shipping_integration_account_id,carrierCode:order.carrier_code,shippingCost:order.shipping_cost_amount}});
   if(claim.error)throw claim.error;if(!claim.data.claimed)return response({ok:true,operations:[claim.data.operation]});operations=[claim.data.operation];
  }
  const results=[];
  for(const op of operations){
   // An in-flight mutation must never be repeated by a refresh request.
   if(refresh&&op.status==='submitting'&&Date.now()-Date.parse(op.created_at)<180000){results.push(op);continue;}
   let result:any,attempted=false;const beforeMutation=async()=>{attempted=true;};try{const snapshot=op.kind==='label'?{...order,shipping_provider:op.provider,shipping_integration_account_id:op.details.shippingAccountId,sendcloud_parcel_id:op.details.parcelId,shipping_remote_id:op.details.shippingRemoteId,tracking_number:op.details.trackingNumber,carrier_code:op.details.carrierCode}:order;result=op.kind==='label'?await cancelCarrier(admin,snapshot,refresh,beforeMutation):await sourceCancel(admin,order,op,refresh,beforeMutation);}catch(error){result={status:refresh?(op.status==='submitting'?'unknown':op.status):!attempted||error instanceof CancellationRejected||/Amazon SP-API \((?:400|401|403|404|422)\)/.test(error instanceof Error?error.message:'')?'rejected':'unknown',message:error instanceof Error?error.message.replace(/(https?:\/\/[^\s?]+)\?[^\s]+/g,'$1?[omitido]').slice(0,800):'No se pudo confirmar la cancelación.'};}
   const saved=await admin.rpc('integration_finish_cancellation',{p_operation_id:op.id,p_owner_id:owner,p_status:result.status,p_message:result.message,p_remote_id:result.remoteId||null});if(saved.error)throw saved.error;results.push({...op,status:result.status,message:result.message,remote_id:result.remoteId||op.remote_id});
  }
  return response({ok:true,operations:results});
 }catch(error){const message=error instanceof Error?error.message:'No se pudo gestionar la cancelación.';return response({error:message},message==='Sesión no válida.'?401:400);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export function sanitizeAmazonError(value:unknown){
  return String(value??'Error desconocido')
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}

export function shopifyError(error:unknown,fallback='No se pudo completar la conexión con Shopify.'):string{
  if(typeof error==='string'&&error.trim()&&error!=='[object Object]')return error.trim();
  if(error&&typeof error==='object'){
    const value=error as Record<string,unknown>;
    for(const key of ['message','error','error_description','details']){
      if(value[key]&&value[key]!==error){const detail=shopifyError(value[key],'');if(detail)return detail;}
    }
  }
  return fallback;
}

export function shopifyDomain(value:unknown){
  const domain=String(value??'').trim().toLowerCase().replace(/^https:\/\//,'').replace(/\/$/,'');
  if(!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(domain))throw new Error('Indica el dominio permanente de Shopify: tienda.myshopify.com, sin rutas.');
  return domain;
}

export function shopifyLegacyCredentials(domain:unknown,accessToken:unknown){
  const token=String(accessToken??'').trim();
  if(!token)throw new Error('Indica el access token de la app antigua.');
  return {shopDomain:shopifyDomain(domain),accessToken:token,authMode:'token'};
}

export function shopifyApplicationCredentials(environment:any,configured:any){
  const candidate=environment?.clientId&&environment?.clientSecret?environment:configured;
  const clientId=String(candidate?.clientId||'').trim(),clientSecret=String(candidate?.clientSecret||'').trim();
  return {clientId,clientSecret,ready:Boolean(clientId&&clientSecret)};
}

export async function shopifyStoredApplicationCredentials(admin:any,ownerId:string){
  const environment={clientId:Deno.env.get('SHOPIFY_CLIENT_ID')||'',clientSecret:Deno.env.get('SHOPIFY_CLIENT_SECRET')||''};
  let configured={};
  if(!environment.clientId||!environment.clientSecret){
    const result=await admin.rpc('integration_read_named_secret',{p_name:`shopify-app:${ownerId}`});
    if(result.error)throw result.error;
    try{configured=JSON.parse(result.data||'{}')}catch{}
  }
  return shopifyApplicationCredentials(environment,configured);
}

export async function shopifyHash(value:string){
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(v=>v.toString(16).padStart(2,'0')).join('');
}

export async function verifyShopifyCallback(params:URLSearchParams,secret:string){
  const keys=[...params.keys()];
  if(new Set(keys).size!==keys.length)return false;
  const supplied=params.get('hmac')||'';
  if(!/^[a-f0-9]{64}$/.test(supplied))return false;
  const message=[...params.entries()].filter(([key])=>key!=='hmac').sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${k}=${v}`).join('&');
  const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);
  const signature=new Uint8Array(supplied.match(/../g)!.map(v=>parseInt(v,16)));
  return crypto.subtle.verify('HMAC',key,signature,new TextEncoder().encode(message));
}

export async function shopifyTokenRequest(domain:string,body:URLSearchParams){
  const res=await fetch(`https://${shopifyDomain(domain)}/admin/oauth/access_token`,{
    method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body,
    redirect:'error',signal:AbortSignal.timeout(20000),
  });
  const token=await res.json().catch(()=>({}));
  if(!res.ok||token.error)throw new Error(token.error==='invalid_client'?'Shopify no acepta el ID o secreto de la app. Comprueba sus credenciales.':token.error==='shop_not_permitted'?'La app y la tienda deben pertenecer a la misma organización Shopify. Para tiendas de clientes utiliza Autorizar con Shopify.':token.error==='invalid_grant'?'Shopify ha caducado o revocado la autorización. Vuelve a conectar la tienda.':`Shopify (${res.status}): no se pudo obtener la autorización. Comprueba que la app esté instalada y tenga permiso read_orders.`);
  return token;
}

export function shopifyTokenCredentials(stored:any,token:any,now=Date.now()){
  if(!token?.access_token)throw new Error('Shopify no devolvió un access token.');
  if(!String(token.scope||'').split(',').includes('read_orders'))throw new Error('La app necesita permiso read_orders. Añádelo en Shopify y vuelve a autorizar.');
  if(token.expires_in!=null&&(!Number.isFinite(Number(token.expires_in))||Number(token.expires_in)<=0))throw new Error('Shopify devolvió una caducidad no válida.');
  return {...stored,accessToken:String(token.access_token),scope:String(token.scope),expiresAt:token.expires_in?now+Number(token.expires_in)*1000:null,...(token.refresh_token?{refreshToken:String(token.refresh_token)}:{})};
}

export async function resolveShopifyCredentials(stored:any,config:any,request=shopifyTokenRequest,persist?: (stored:any)=>Promise<unknown>){
  const domain=shopifyDomain(stored.shopDomain||stored.shop_domain||config.shopDomain);
  let token=String(stored.accessToken||stored.access_token||'').trim();
  if(!token||(stored.expiresAt&&Number(stored.expiresAt)<=Date.now()+300000)){
    const clientId=stored.clientId||Deno.env.get('SHOPIFY_CLIENT_ID');
    const clientSecret=stored.clientSecret||Deno.env.get('SHOPIFY_CLIENT_SECRET');
    if(!clientId||!clientSecret)throw new Error('Renueva la conexión con Shopify desde Integraciones.');
    const fields:Record<string,string>={client_id:clientId,client_secret:clientSecret};
    if(stored.authMode==='client_credentials')fields.grant_type='client_credentials';
    else if(stored.refreshToken){fields.grant_type='refresh_token';fields.refresh_token=stored.refreshToken;}
    else throw new Error('Renueva la autorización de Shopify desde Integraciones.');
    const renewed=shopifyTokenCredentials(stored,await request(domain,new URLSearchParams(fields)));
    if(persist)await persist(renewed);
    token=renewed.accessToken;
  }
  return {shopDomain:domain,accessToken:token,apiVersion:String(config.apiVersion||'2026-07')};
}

export async function shopifyAccountCredentials(admin:any,account:any,appCredentials?:{clientId:string;clientSecret:string}){
  async function read(){
    const result=await admin.from('integration_accounts').select('*').eq('id',account.id).eq('owner_id',account.owner_id).maybeSingle();
    if(result.error)throw result.error;
    if(!result.data?.enabled||result.data.status==='disabled')throw new Error('La cuenta Shopify está desconectada.');
    const secret=await admin.rpc('integration_read_secret',{p_secret_id:result.data.secret_id});
    if(secret.error)throw secret.error;
    return {row:result.data,stored:JSON.parse(secret.data||'{}')};
  }
  let current=await read();
  if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  const lease=crypto.randomUUID();
  let claimed=false;
  for(let attempt=0;attempt<125;attempt++){
    const result=await admin.rpc('integration_shopify_claim_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
    if(result.error)throw result.error;
    if(result.data){claimed=true;break;}
    await new Promise(resolve=>setTimeout(resolve,200));
    current=await read();
    if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  }
  if(!claimed)throw new Error('Shopify está renovando la autorización. Vuelve a intentarlo en unos segundos.');
  try{
    current=await read();
    if(current.stored.authMode==='oauth'&&appCredentials&&current.stored.clientId!==appCredentials.clientId)throw new Error('La app Shopify cambió. Vuelve a autorizar esta tienda.');
    const storedForRenewal=current.stored.authMode==='oauth'&&appCredentials?{...current.stored,clientSecret:appCredentials.clientSecret}:current.stored;
    return await resolveShopifyCredentials(storedForRenewal,current.row.config||{},shopifyTokenRequest,async stored=>{
      if(current.stored.authMode==='oauth')delete stored.clientSecret;
      const result=await admin.rpc('integration_shopify_commit_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease,p_version:current.row.shopify_credential_version,p_secret:JSON.stringify(stored)});
      if(result.error)throw result.error;
      if(!result.data)throw new Error('La conexión de Shopify cambió durante la renovación. Vuelve a intentarlo.');
    });
  }finally{
    await admin.rpc('integration_shopify_release_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
  }
}

export async function commitShopifyAuthorization(admin:any,account:any,pending:any,stored:any){
  const config={...(account.config||{}),shopDomain:stored.shopDomain,authMode:'oauth',syncOrders:pending.syncOrders!==false,apiVersion:'2026-07'};
  delete config.oauthStateHash;
  const result=await admin.rpc('integration_shopify_complete_oauth',{p_account_id:account.id,p_owner_id:account.owner_id,p_version:account.shopify_credential_version,p_secret:JSON.stringify(stored),p_display_name:pending.displayName||account.display_name,p_config:config});
  if(result.error)throw result.error;
  if(!result.data)throw new Error('La conexión de Shopify cambió mientras autorizabas. Vuelve a conectar la tienda.');
}

const cancellationReasons:any={customer:{amazon:'BuyerCanceled',shopify:'CUSTOMER'},inventory:{amazon:'NoInventory',shopify:'INVENTORY'},address:{amazon:'ShippingAddressUndeliverable',shopify:'OTHER'},other:{amazon:'GeneralAdjustment',shopify:'OTHER'}};
